import AWSXRay from 'aws-xray-sdk-core';

async function chargeCard(orderId: string) {
  const segment = AWSXRay.getSegment();
  const sub = segment?.addNewSubsegment('chargeCard');
  try {
    sub?.addAnnotation('orderId', orderId);
    await paymentApi.charge(orderId);
  } catch (err) {
    sub?.addError(err as Error);
    throw err;
  } finally {
    sub?.close();
  }
}
